from __future__ import annotations
from itertools import product
from math import cosh, exp, sinh

def direct(n: int, beta: float) -> float:
    return sum(exp(beta * sum(s[i] * s[(i + 1) % n] for i in range(n)))
               for s in product((-1, 1), repeat=n))

def closed(n: int, beta: float) -> float:
    return (2 * cosh(beta)) ** n + (2 * sinh(beta)) ** n

if __name__ == "__main__":
    for n in range(2, 11):
        a, b = direct(n, 0.8), closed(n, 0.8)
        print(n, a, b, abs(a-b))

from __future__ import annotations
from math import exp

def majorant(beta: float, minimum_length: int = 4) -> float:
    q = 3.0 * exp(-2.0 * beta)
    if not 0.0 < q < 1.0:
        raise ValueError("series does not converge")
    return q ** minimum_length / (1.0 - q)

if __name__ == "__main__":
    for beta in (0.8, 1.0, 1.2, 1.5, 2.0):
        bound = majorant(beta)
        print(beta, bound, "positive-magnetization criterion" if bound < 0.5 else "inconclusive")

